fun completeSetup(permissionRequestLaunched: Boolean): Boolean { isWaitingForPermissionResult = permissionRequestLaunched return !permissionRequestLaunched }
fun onPermissionRequestFinished(): Boolean { if (!isWaitingForPermissionResult) return false isWaitingForPermissionResult = false return true } }
