private fun resetInactivityTimer() { inactivityHandler.removeCallbacks(inactivityRunnable) inactivityHandler.postDelayed(inactivityRunnable, 5 * 60 * 1000L) }
override fun dispatchTouchEvent(ev: android.view.MotionEvent?): Boolean { if (ev?.action == android.view.MotionEvent.ACTION_DOWN) { resetInactivityTimer() } return super.dispatchTouchEvent(ev) }
override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) resetInactivityTimer() onboardingPermissionFlow = OnboardingPermissionFlow( savedInstanceState?.getBoolean(ONBOARDING_PERMISSION_PENDING_STATE_KEY) == true ) pendingContactSupportNotification = intent.toContactSupportNotification() pendingAnnouncementNotification = intent.toAnnouncementNotification() SupportNotificationChannel.create(this) MobileAds.initialize(this) requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_PORTRAIT enableEdgeToEdge() androidx.core.view.WindowCompat.getInsetsController(window, window.decorView).apply { isAppearanceLightStatusBars = false isAppearanceLightNavigationBars = false }
