setContent { KolamMasterKotlinTheme { LocalizedAppResources(activeLanguage) { KolamMasterApp( screen = screenState, onScreenChange = { screenState = it }, activeLanguage = activeLanguage, catalogue = catalogueState, unlockedCatalogueLessonIds = unlockedCatalogueLessonIds, visibleLessonCount = visibleLessonCount, assetSetupProgress = assetSetupProgress, isAssetSetupRunning = assetSetupRunning, assetSetupError = assetSetupError, account = accountState, isAuthProcessing = isAuthProcessing, publishPickerLesson = publishPickerLesson, authLoadingMessage = authLoadingMessage, authError = authError, authErrorTitle = authErrorTitle, onNavigate = ::navigateTo, onLessonUnlocked = ::recordLessonUnlock, onVisibleLessonCountChanged = ::recordVisibleLessonCount, onRetryAssetSetup = ::startInitialAssetSetup, onGoBack = ::goBack, onHome = { setRoot(AppScreen.Landing) }, onReturnToCatalogue = { setRoot(AppScreen.Browse) }, onGoogleSignIn = ::beginGoogleSignIn, onContinueAsGuest = ::continueAsGuest, onSignOut = ::signOutToGuest, onDismissAuthError = { authError = null }, onLanguageChange = { language -> saveLanguage(language) goBack() }, onLanguageSelected = { language -> setInitialAssetAuthComplete(false) saveLanguage(language) routeHistory.clear() routeHistory += AppScreen.ChooseLanguage screenState = AppScreen.SignInInvitation }, onLanguageBack = { finish() }, onLoadLesson = { lesson -> loadLesson(lesson) }, onLoadCommunityLesson = { lesson -> loadLesson(lesson, fromCommunity = true) }, onCheckMoreThumbnails = ::checkLessonCatalogueUpdates, communityLessonOpenError = communityLessonOpenError, onDismissCommunityLessonOpenError = { communityLessonOpenError = null }, onCommunityLessonMissing = { communityLessonOpenError = withSelectedAppLanguage().getString( R.string.community_lesson_missing ) goBack() }, onPublishLesson = ::requestPublish, onDismissPublishPicker = { publishPickerLesson = null }, onPublishImagesSelected = ::openGalleryPublishForm, supportNotification = pendingContactS