override fun onSaveInstanceState(outState: Bundle) { outState.putBoolean( ONBOARDING_PERMISSION_PENDING_STATE_KEY, onboardingPermissionFlow.isWaitingForPermissionResult ) super.onSaveInstanceState(outState) }
override fun onNewIntent(intent: Intent) { super.onNewIntent(intent) setIntent(intent) pendingContactSupportNotification = intent.toContactSupportNotification() pendingAnnouncementNotification = intent.toAnnouncementNotification() }
override fun onResume() { super.onResume() resetInactivityTimer() recordCurrentUserActivity() AnnouncementRepository.requestRefresh(this) refreshLauncherBadgeFromCache() }
