private fun recordCurrentUserActivity() { lifecycleScope.launch { try { val account = SupabaseGuestAuth.currentAccount() ?: return@launch recordCurrentUserActivity(account.id) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.w("LastActivity", "Could not resolve the current user for activity tracking.", exception) } } }
private fun recordCurrentUserActivity(userId: String) { val now = SystemClock.elapsedRealtime() if (lastActivityAttemptUserId == userId && now - lastActivityAttemptElapsedRealtime < LAST_ACTIVITY_MIN_INTERVAL_MILLIS ) { return } lastActivityAttemptUserId = userId lastActivityAttemptElapsedRealtime = now lifecycleScope.launch { try { lastActivityRepository.recordCurrentUserActivity(userId) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.w("LastActivity", "Could not update Last Activity in Supabase.", exception) } } }
private fun refreshLauncherBadgeFromCache() { lifecycleScope.launch { try { val account = SupabaseGuestAuth.currentAccount() if (account == null) { LauncherBadgeHelper.updateExistingNotification( this@MainActivity, PendingAnnouncementStore.count(this@MainActivity) + SupportUnreadStore.unreadMessageCount(this@MainActivity) ) return@launch } SupportUnreadStore.useAccount(this@MainActivity, account.id) val announcements = AnnouncementRepository(this@MainActivity).loadCached(account) val announcementUnreadCount = PendingAnnouncementStore.reconcile( this@MainActivity, announcements.count { !it.isRead }, announcements.map(Announcement::id).toSet() ) LauncherBadgeHelper.updateExistingNotification( this@MainActivity, announcementUnreadCount + SupportUnreadStore.unreadMessageCount(this@MainActivity) ) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LauncherBadge", "Could not recalculate the launcher badge count.", exception) } } }
private fun beginGoogleSignIn() { if (isAuthProcessing) return isAuthProcessing = true authLoadingMessage = R.string.signing_in authError = null googleChooserTimeoutJob?.cancel() lifecycleScope.launch { try { val currentAccount = runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { SupabaseGuestAuth.currentAccount() } if (currentAccount != null && !currentAccount.isGuest) { accountState = currentAccount restoreLessonUnlocks(currentAccount) openPendingPublishAfterSignIn(currentAccount) if (screenState == AppScreen.SignInInvitation) { val waitingForPermission = continueOnboardingAfterPermission() if (waitingForPermission) return@launch } clearAuthProcessing() return@launch } runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { SupabaseGuestAuth.getOrCreateGuestUserId() } authLoadingMessage = null googleSignInAwaitingResult = true googleSignInLauncher.launch(googleSignInClient.signInIntent) googleChooserTimeoutJob = lifecycleScope.launch { delay(GOOGLE_CHOOSER_TIMEOUT_MILLIS) if (isAuthProcessing) { googleSignInAwaitingResult = false pendingPublishLesson = null authErrorTitle = AUTH_SIGN_IN_PROBLEM authError = AUTH_SIGN_IN_TIMEOUT isAuthProcessing = false authLoadingMessage = null } } } catch (exception: CancellationException) { pendingPublishLesson = null clearAuthProcessing() throw exception } catch (exception: Exception) { pendingPublishLesson = null showGoogleSignInError(exception) } } }
private fun finishGoogleSignIn(idToken: String) { lifecycleScope.launch { var waitingForPermission = false try { authLoadingMessage = R.string.signing_in val (previousAccount, newAccount) = runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { SupabaseGuestAuth.currentAccount() to SupabaseGuestAuth.mergeGuestWithGoogleIdToken(idToken) } if (previousAccount?.isGuest == true && previousAccount.id != newAccount.id ) { try { val guestUnlocks = lessonUnlockRepository.loadLocal(previousAccount.id) val accountUnlocks = lessonUnlockRepository.loadLocal(newAccount.id) lessonUnlockRepository.saveLocal( newAccount.id, accountUnlocks + guestUnlocks ) val guestVisibleCount = lessonUnlockRepository.loadLocalVisibleLessonCount(previousAccount.id) val accountVisibleCount = lessonUnlockRepository.loadLocalVisibleLessonCount(newAccount.id) visibleLessonCount = lessonUnlockRepository.saveLocalVisibleLessonCount( newAccount.id, maxOf(guestVisibleCount, accountVisibleCount) ) } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not migrate Guest lesson data locally.", exception) } } accountState = newAccount recordCurrentUserActivity(newAccount.id) registerFcmToken(newAccount) restoreLessonUnlocks(newAccount) openPendingPublishAfterSignIn(newAccount) if (screenState == AppScreen.SignInInvitation) { waitingForPermission = continueOnboardingAfterPermission() }
} catch (exception: CancellationException) { pendingPublishLesson = null throw exception } catch (exception: Exception) { pendingPublishLesson = null showGoogleSignInError(exception) } finally { if (!waitingForPermission) clearAuthProcessing() } } }
private fun continueAsGuest() { if (isAuthProcessing) return isAuthProcessing = true authLoadingMessage = R.string.continuing_as_guest authError = null lifecycleScope.launch { var waitingForPermission = false try { runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { val currentAccount = SupabaseGuestAuth.currentAccount() if (currentAccount == null || currentAccount.isGuest) { SupabaseGuestAuth.getOrCreateGuestUserId() }
accountState = SupabaseGuestAuth.currentAccount() accountState?.let { restoreLessonUnlocks(it) registerFcmToken(it) } } waitingForPermission = continueOnboardingAfterPermission() } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { showAuthError(exception) } finally { if (!waitingForPermission) clearAuthProcessing() } } }
private fun requestPublish(lesson: PublishLessonDetails) { if (!hasValidatedInternetConnection()) { authErrorTitle = NetworkErrors.TITLE authError = NetworkErrors.MESSAGE return } pendingPublishLesson = lesson lifecycleScope.launch { try { val currentAccount = runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { SupabaseGuestAuth.currentAccount() } if (currentAccount != null && !currentAccount.isGuest) { accountState = currentAccount openPendingPublishAfterSignIn(currentAccount) } else { beginGoogleSignIn() } } catch (exception: CancellationException) { pendingPublishLesson = null throw exception } catch (exception: Exception) { pendingPublishLesson = null showGoogleSignInError(exception) } } }
private fun openPendingPublishAfterSignIn(account: SupabaseAccount) { val lesson = pendingPublishLesson ?: return if (account.isGuest) return pendingPublishLesson = null publishPickerLesson = lesson }
private fun openGalleryPublishForm( lesson: PublishLessonDetails, imageUris: List<Uri>, temporaryImageUris: Set<Uri> ) { publishPickerLesson = null navigateTo(AppScreen.PublishReady(lesson, imageUris, temporaryImageUris)) }
private fun hasValidatedInternetConnection(): Boolean { val connectivity = getSystemService(ConnectivityManager::class.java) ?: return false val network = connectivity.activeNetwork ?: return false return connectivity.getNetworkCapabilities(network)?.let { capabilities -> capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) && capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) } == true }
private fun continueOnboardingAfterPermission(): Boolean { setInitialAssetAuthComplete(true) val preferences = getSharedPreferences(PREFERENCES_NAME, MODE_PRIVATE) val permissionGranted = Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU || checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED val shouldRequest = shouldRequestNotificationPermission( sdkInt = Build.VERSION.SDK_INT, permissionGranted = permissionGranted, permissionPreviouslyRequested = preferences.getBoolean( NOTIFICATIONS_PERMISSION_REQUESTED_KEY, false ) ) if (onboardingPermissionFlow.completeSetup(shouldRequest)) { startInitialAssetSetup() return false }
preferences.edit() .putBoolean(NOTIFICATIONS_PERMISSION_REQUESTED_KEY, true) .commit() authLoadingMessage = null try { notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS) } catch (exception: Exception) { onboardingPermissionFlow.onPermissionRequestFinished() throw exception } return true }
private fun isInitialAssetSetupComplete(): Boolean = getSharedPreferences(ASSET_SETUP_PREFERENCES_NAME, MODE_PRIVATE) .getBoolean(ASSET_SETUP_COMPLETE_KEY, false)
private fun isInitialAssetAuthComplete(defaultValue: Boolean): Boolean = getSharedPreferences(ASSET_SETUP_PREFERENCES_NAME, MODE_PRIVATE) .getBoolean(INITIAL_ASSET_AUTH_COMPLETE_KEY, defaultValue)
private fun setInitialAssetAuthComplete(complete: Boolean) { check( getSharedPreferences(ASSET_SETUP_PREFERENCES_NAME, MODE_PRIVATE) .edit() .putBoolean(INITIAL_ASSET_AUTH_COMPLETE_KEY, complete) .commit() ) { "Could not save onboarding completion." } }
private fun startInitialAssetSetup() { if (isInitialAssetSetupComplete()) { assetSetupRunning = false assetSetupError = null screenState = AppScreen.Opening return } if (assetSetupJob?.isActive == true) return
screenState = AppScreen.DownloadingAssets assetSetupRunning = true assetSetupError = null assetSetupProgress = AssetSetupProgress( 0, 0, AssetSetupMessage.PreparingImages ) assetSetupJob = lifecycleScope.launch { try { val catalogueRepository = LessonCatalogueRepository(this@MainActivity) val setup = InitialAssetSetup( isComplete = ::isInitialAssetSetupComplete, markComplete = { check( getSharedPreferences(ASSET_SETUP_PREFERENCES_NAME, MODE_PRIVATE) .edit() .putBoolean(ASSET_SETUP_COMPLETE_KEY, true) .commit() ) { "Could not save initial asset setup completion." } }, loadLessons = { val entries = catalogueRepository.refresh() catalogueState = LessonCatalogueUiState( entries = entries, isInitialLoading = false ) entries }, cacheLessonThumbnails = { urls, reportProgress -> LessonThumbnailCache.prefetch( this@MainActivity, urls, { completed, total -> withContext(Dispatchers.Main.immediate) { reportProgress(completed, total) } } ) } ) val completed = setup.run { progress -> assetSetupProgress = progress } if (!completed) { error("One or more required images could not be downloaded.") } assetSetupRunning = false screenState = AppScreen.Opening } catch (exception: CancellationException) { assetSetupRunning = false throw exception } catch (exception: Exception) { Log.e("InitialAssetSetup", "Could not prepare initial app images.", exception) assetSetupRunning = false assetSetupError = R.string.some_images_failed } } }
private fun signOutToGuest() { if (isAuthProcessing) return isAuthProcessing = true authLoadingMessage = R.string.signing_out authError = null lifecycleScope.launch { try { googleSignInClient.signOut() try { runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { PushTokenRepository(applicationContext).unregisterCurrentUserToken() } } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("PushNotifications", "Could not unregister the current FCM token.", exception) } runBoundedNetworkOperation(SIGN_IN_SDK_TIMEOUT_MILLIS) { SupabaseGuestAuth.signOutAndCreateGuest() accountState = SupabaseGuestAuth.currentAccount() accountState?.let { restoreLessonUnlocks(it) registerFcmToken(it) } } } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { showAuthError(exception) } finally { clearAuthProcessing() } } }
private fun showAuthError( exception: Exception, fallback: String = AUTH_SIGN_IN_PROBLEM, exposeNonNetworkDetails: Boolean = true ) { val networkFailure = NetworkErrors.isNetworkFailure(exception) authErrorTitle = if (networkFailure) NetworkErrors.TITLE else AUTH_SIGN_IN_PROBLEM authError = if (networkFailure) { NetworkErrors.MESSAGE } else if (exposeNonNetworkDetails && !NetworkErrors.isHttpFailure(exception)) { exception.message?.takeIf(String::isNotBlank) ?: fallback } else { fallback } clearAuthProcessing() }
private fun showGoogleSignInError( exception: Exception, fallback: String = AUTH_GOOGLE_SIGN_IN_FAILED, exposeNonNetworkDetails: Boolean = true ) { val networkMessage = NetworkErrors.googleSignInNetworkMessage(exception) if (networkMessage != null) { authErrorTitle = NetworkErrors.GOOGLE_SIGN_IN_TITLE authError = networkMessage clearAuthProcessing() } else { showAuthError(exception, fallback, exposeNonNetworkDetails) } }
private fun clearAuthProcessing() { googleChooserTimeoutJob?.cancel() googleChooserTimeoutJob = null googleSignInAwaitingResult = false isAuthProcessing = false authLoadingMessage = null }
private fun showNetworkIssue() { authErrorTitle = NetworkErrors.TITLE authError = NetworkErrors.MESSAGE }
private fun restoreLessonUnlocks(account: SupabaseAccount) { val generation = ++unlockRestoreGeneration val localUnlocks = lessonUnlockRepository.loadLocal(account.id) val localVisibleCount = lessonUnlockRepository.loadLocalVisibleLessonCount(account.id) visibleLessonCount = localVisibleCount unlockedCatalogueLessonIds = localUnlocks lifecycleScope.launch { val remoteData = try { lessonUnlockRepository.loadFromSupabase(account.id) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not load lesson unlocks from Supabase.", exception) return@launch } if (!isCurrentUnlockAccount(account.id, generation)) return@launch
val latestLocalUnlocks = lessonUnlockRepository.loadLocal(account.id) val mergedUnlocks = latestLocalUnlocks + localUnlocks + unlockedCatalogueLessonIds + remoteData.unlockedLessonIds val mergedVisibleCount = lessonUnlockRepository.saveLocalVisibleLessonCount( account.id, maxOf(localVisibleCount, remoteData.visibleLessonCount) ) try { lessonUnlockRepository.saveLocal(account.id, mergedUnlocks) } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not persist merged lesson unlocks locally.", exception) } unlockedCatalogueLessonIds = mergedUnlocks visibleLessonCount = mergedVisibleCount if (mergedUnlocks != remoteData.unlockedLessonIds || mergedVisibleCount != remoteData.visibleLessonCount ) { try { lessonUnlockRepository.saveToSupabase( account.id, mergedUnlocks, mergedVisibleCount ) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e( "LessonUnlocks", "Could not sync merged lesson unlocks to Supabase.", exception ) } } } }
private fun registerFcmToken(account: SupabaseAccount) { FirebaseMessaging.getInstance().token .addOnSuccessListener { token -> lifecycleScope.launch { try { val current = SupabaseGuestAuth.currentAccount() if (current != null && current.id == account.id) { PushTokenRepository(applicationContext).registerCurrentToken(token) } } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("PushNotifications", "Could not register the FCM token.", exception) } } } .addOnFailureListener { exception -> Log.e("PushNotifications", "Could not obtain an FCM registration token.", exception) } }
private fun recordLessonUnlock(lessonId: String) { unlockedCatalogueLessonIds = unlockedCatalogueLessonIds + lessonId val account = accountState if (account != null) { val localUnlocks = lessonUnlockRepository.loadLocal(account.id) + unlockedCatalogueLessonIds try { lessonUnlockRepository.saveLocal(account.id, localUnlocks) } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not persist lesson unlock locally.", exception) } syncLessonUnlocks(account, localUnlocks, notifyNetworkFailure = true) return }
lifecycleScope.launch { try { val resolvedAccount = SupabaseGuestAuth.currentAccount() ?: run { SupabaseGuestAuth.getOrCreateGuestUserId() SupabaseGuestAuth.currentAccount() } ?: error("Could not resolve an account for lesson unlock storage.") accountState = resolvedAccount val localUnlocks = lessonUnlockRepository.loadLocal(resolvedAccount.id) + lessonId lessonUnlockRepository.saveLocal(resolvedAccount.id, localUnlocks) unlockedCatalogueLessonIds = localUnlocks syncLessonUnlocks(resolvedAccount, localUnlocks, notifyNetworkFailure = true) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not persist lesson unlock locally.", exception) if (NetworkErrors.isNetworkFailure(exception)) showNetworkIssue() } } }
private fun recordVisibleLessonCount(newCount: Int) { visibleLessonCount = maxOf(visibleLessonCount, newCount) lifecycleScope.launch { try { val account = accountState ?: SupabaseGuestAuth.currentAccount() ?: run { SupabaseGuestAuth.getOrCreateGuestUserId() SupabaseGuestAuth.currentAccount() } ?: error("Could not resolve an account for visible lesson storage.") accountState = account val mergedCount = lessonUnlockRepository.saveLocalVisibleLessonCount( account.id, visibleLessonCount ) visibleLessonCount = mergedCount syncLessonUnlocks( account, lessonUnlockRepository.loadLocal(account.id) + unlockedCatalogueLessonIds ) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not persist the visible lesson count.", exception) if (NetworkErrors.isNetworkFailure(exception)) showNetworkIssue() } } }
private fun syncLessonUnlocks( account: SupabaseAccount, localUnlocks: Set<String>, notifyNetworkFailure: Boolean = false ) { val generation = unlockRestoreGeneration lifecycleScope.launch { val remoteData = try { lessonUnlockRepository.loadFromSupabase(account.id) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not load lesson unlocks before sync.", exception) if (notifyNetworkFailure && NetworkErrors.isNetworkFailure(exception)) { showNetworkIssue() } return@launch } if (!isCurrentUnlockAccount(account.id, generation)) return@launch
val mergedUnlocks = lessonUnlockRepository.loadLocal(account.id) + localUnlocks + unlockedCatalogueLessonIds + remoteData.unlockedLessonIds val mergedVisibleCount = lessonUnlockRepository.saveLocalVisibleLessonCount( account.id, maxOf( lessonUnlockRepository.loadLocalVisibleLessonCount(account.id), remoteData.visibleLessonCount ) ) try { lessonUnlockRepository.saveLocal(account.id, mergedUnlocks) } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not persist synced lesson unlocks locally.", exception) } unlockedCatalogueLessonIds = mergedUnlocks visibleLessonCount = mergedVisibleCount if (mergedUnlocks != remoteData.unlockedLessonIds || mergedVisibleCount != remoteData.visibleLessonCount ) { try { lessonUnlockRepository.saveToSupabase( account.id, mergedUnlocks, mergedVisibleCount ) } catch (exception: CancellationException) { throw exception } catch (exception: Exception) { Log.e("LessonUnlocks", "Could not sync lesson unlocks to Supabase.", exception) if (notifyNetworkFailure && NetworkErrors.isNetworkFailure(exception)) { showNetworkIssue() } } } } }
private fun isCurrentUnlockAccount(userId: String, generation: Int): Boolean = generation == unlockRestoreGeneration && accountState?.id == userId
private fun refreshLessonCatalogue() { val repository = LessonCatalogueRepository(this) lifecycleScope.launch { val cachedEntries = repository.loadCached() catalogueState = LessonCatalogueUiState( entries = cachedEntries, isInitialLoading = cachedEntries.isEmpty(), isRefreshing = true ) try { val freshEntries = repository.refresh() catalogueState = LessonCatalogueUiState( entries = freshEntries, isInitialLoading = false, isRefreshing = false ) } catch (exception: IOException) { Log.w("LessonCatalogue", "Could not refresh public lesson catalogue", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = NetworkErrors.isNetworkFailure(exception) ) } catch (exception: JSONException) { Log.w("LessonCatalogue", "R2 returned invalid lesson catalogue JSON", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = false ) } catch (exception: CancellationException) { catalogueState = catalogueState.copy(isInitialLoading = false, isRefreshing = false) throw exception } catch (exception: Exception) { Log.e("LessonCatalogue", "Unexpected catalogue refresh failure", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = false ) } } }
private suspend fun checkLessonCatalogueUpdates(): List<LessonCatalogueEntry> { catalogueState = catalogueState.copy( isRefreshing = true, refreshFailed = false, refreshNetworkFailed = false ) try { val freshEntries = LessonCatalogueRepository(this).refresh() catalogueState = LessonCatalogueUiState( entries = freshEntries, isInitialLoading = false ) return freshEntries } catch (exception: CancellationException) { catalogueState = catalogueState.copy(isInitialLoading = false, isRefreshing = false) throw exception } catch (exception: IOException) { Log.w("LessonCatalogue", "Could not check for new catalogue lessons", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = NetworkErrors.isNetworkFailure(exception) ) throw exception } catch (exception: JSONException) { Log.w("LessonCatalogue", "R2 returned invalid lesson catalogue JSON", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = false ) throw exception } catch (exception: Exception) { Log.e("LessonCatalogue", "Unexpected catalogue update check failure", exception) catalogueState = catalogueState.copy( isInitialLoading = false, isRefreshing = false, refreshFailed = true, refreshNetworkFailed = false ) throw exception } }
private fun saveLanguage(language: String) { activeLanguage = language getSharedPreferences(PREFERENCES_NAME, MODE_PRIVATE) .edit() .putString(LANGUAGE_KEY, language) .apply() }
private fun navigateTo(destination: AppScreen) { routeHistory += screenState screenState = destination }
private fun setRoot(destination: AppScreen) { routeHistory.clear() screenState = destination }
private fun goBack() { screenState = routeHistory.removeLastOrNull() ?: AppScreen.Landing }
private fun loadLesson(lesson: LessonCatalogueEntry, fromCommunity: Boolean = false) { if (!fromCommunity) routeHistory += AppScreen.Browse val lessonType = lesson.normalizedType if (lessonType == null) { showLessonLoadFailure( "This lesson has an unsupported Kolam type.", fromCommunity ) return } val packageUrl = lesson.packageUrls.firstOrNull() if (packageUrl.isNullOrBlank()) { showLessonLoadFailure( "This lesson does not have a downloadable package.", fromCommunity ) return }
screenState = if (fromCommunity) AppScreen.Loading else AppScreen.LessonDownloading lifecycleScope.launch { try { val loadedScreen = withContext(Dispatchers.IO) { val destination = File( File(cacheDir, "catalogue-lessons"), packageUrl.toByteArray(Charsets.UTF_8).sha256Hex() ) val isCachedValid = destination.isDirectory && File(destination, "path.json").isFile if (!isCachedValid) { KmpLessonExtractor.extractPackage( encryptedPackage = downloadLessonPackage(packageUrl), sharedSecret = KmpSecret.value(), destination = destination ) } if (lessonType == "Rangoli") { AppScreen.RangoliReady( RangoliLesson.load(destination, lesson.dotInformation), lesson.toPublishLessonDetails() ) } else { AppScreen.SikkuReady( SikkuLesson.load(destination, lesson.dotInformation), lesson.toPublishLessonDetails() ) } } screenState = loadedScreen } catch (e: IOException) { Log.e("KmpLesson", "Could not read lesson assets", e) showLessonLoadFailure( NetworkErrors.messageFor(e, e.message ?: "Could not read lesson files"), fromCommunity ) } catch (e: GeneralSecurityException) { Log.e("KmpLesson", "Could not decrypt lesson package", e) showLessonLoadFailure(e.message ?: "Could not decrypt lesson", fromCommunity) } catch (e: JSONException) { Log.e("KmpLesson", "Invalid lesson JSON data", e) showLessonLoadFailure(e.message ?: "Invalid lesson data", fromCommunity) } catch (e: IllegalArgumentException) { Log.e("KmpLesson", "Invalid lesson package", e) showLessonLoadFailure(e.message ?: "Invalid lesson package", fromCommunity) } catch (e: CancellationException) { if (screenState == AppScreen.Loading || screenState == AppScreen.LessonDownloading ) { screenState = if (fromCommunity) AppScreen.Community else AppScreen.Browse } throw e } catch (e: Exception) { Log.e("KmpLesson", "Unexpected lesson loading failure", e) showLessonLoadFailure( e.message?.takeIf(String::isNotBlank) ?: withSelectedAppLanguage().getString(R.string.lessons_load_failed), fromCommunity ) } finally { if (screenState == AppScreen.Loading || screenState == AppScreen.LessonDownloading ) { screenState = if (fromCommunity) AppScreen.Community else AppScreen.Browse } } } }
private fun showLessonLoadFailure(message: String, fromCommunity: Boolean) { if (fromCommunity) { communityLessonOpenError = message screenState = AppScreen.Community } else { screenState = AppScreen.Failed(message) } }
private fun downloadLessonPackage(packageUrl: String): ByteArray { val connection = URL(packageUrl).openConnection() as? HttpsURLConnection ?: throw IOException("Lesson package URL must use HTTPS") try { connection.requestMethod = "GET" connection.connectTimeout = 15_000 connection.readTimeout = 30_000 val status = connection.responseCode if (status !in 200..299) { throw HttpStatusFailureException( statusCode = status, message = "Lesson package request failed with HTTP $status" ) } return connection.inputStream.use { it.readBytes() } } finally { connection.disconnect() } }
private companion object { const val SIGN_IN_SDK_TIMEOUT_MILLIS = 90_000L const val GOOGLE_CHOOSER_TIMEOUT_MILLIS = 180_000L } }
private fun ByteArray.sha256Hex(): String = MessageDigest.getInstance("SHA-256") .digest(this) .joinToString("") { byte -> "%02x".format(byte) }
internal fun Intent.toContactSupportNotification(): ContactSupportNotification? { if (!getStringExtra("type").equals("support_message", ignoreCase = true) || !getStringExtra("sender").equals("ADMIN", ignoreCase = true) ) return null val conversationId = sequenceOf( getStringExtra("conversationId"), getStringExtra("conversation_id") ).firstOrNull { !it.isNullOrBlank() } val messageId = sequenceOf( getStringExtra("messageId"), getStringExtra("message_id"), getStringExtra("id") ).firstOrNull { !it.isNullOrBlank() } return ContactSupportNotification( conversationId = conversationId?.takeIf(String::isNotBlank), messageId = messageId?.takeIf(String::isNotBlank) ) }
private fun Intent.toAnnouncementNotification(): AnnouncementNotification? { if (!getStringExtra("type").let { it.equals("announcement", ignoreCase = true) || it.equals("announcement_message", ignoreCase = true) } ) return null return AnnouncementNotification( announcementId = sequenceOf( getStringExtra("announcementId"), getStringExtra("announcement_id") ).firstOrNull { !it.isNullOrBlank() } ) }
