}

private fun luminance(color: Int): Int =
    (0.2126f * Color.red(color) + 0.7152f * Color.green(color) +
        0.0722f * Color.blue(color) + 0.5f).toInt().coerceIn(0, 255)

internal fun readStepPolygonData(root: JSONObject): Map<Int, LessonPolygonStep> {
    val polygonValue = root.opt("polygons") ?: return emptyMap()
    if (polygonValue == JSONObject.NULL) return emptyMap()
    val entries = polygonValue as? JSONArray
        ?: throw IOException("path.json polygons field is not an array")
    val polygonsByStep = linkedMapOf<Int, MutableList<LessonPolygon>>()
    for (entryIndex in 0 until entries.length()) {
        val entry = entries.optJSONObject(entryIndex)
            ?: throw IOException("Polygon entry $entryIndex is not an object")
        val stepNumber = sequenceOf("lesson", "lessonNumber", "step", "stepNumber", "teachingStep")
            .firstNotNullOfOrNull { key ->
                if (entry.has(key)) entry.optInt(key).takeIf { it > 0 } else null
            } ?: throw IOException("Polygon entry $entryIndex has no valid teaching step")

        val regionArray = entry.optJSONArray("regions")
            ?: entry.optJSONArray("polygons")
            ?: if (entry.has("vertices") || entry.has("points")) {
                JSONArray().put(entry)
            } else {
                throw IOException("Polygon entry for step $stepNumber has no regions")
            }
        if (regionArray.length() == 0) {
            throw IOException("Polygon entry for step $stepNumber has no regions")
        }

        val regions = polygonsByStep.getOrPut(stepNumber) { mutableListOf() }
        val firstRegionItem = regionArray.opt(0)
        val isDirectVertexList = when (firstRegionItem) {
            is JSONObject -> firstRegionItem.has("x") && firstRegionItem.has("y")
            is JSONArray -> firstRegionItem.opt(0) is Number
            else -> false
        }
        val regionEntries = if (isDirectVertexList) {
            listOf(regionArray)
        } else {
            (0 until regionArray.length()).map { regionArray.get(it) }
        }
        for ((regionIndex, region) in regionEntries.withIndex()) {
            val (vertices, polygonId, isHole) = when (region) {
                is JSONObject -> Triple(
                    region.optJSONArray("vertices")
                        ?: region.optJSONArray("points")
                        ?: region.optJSONArray("coordinates")
                        ?: throw IOException("Polygon region $regionIndex has no vertices"),
                    jsonIdentifier(region.opt("id")),
                    region.opt("hole") as? Boolean ?: false
                )
                is JSONArray -> Triple(region, null, false)
                else -> throw IOException(
                    "Polygon region $regionIndex for step $stepNumber is invalid"
                )
            }
            if (vertices.length() < 3) {
                throw IOException("Polygon region $regionIndex has fewer than three vertices")
            }
            val points = buildList {
                for (vertexIndex in 0 until vertices.length()) {
                    val vertex = vertices.get(vertexIndex)
                    val point = when (vertex) {
                        is JSONObject -> LessonPoint(
                            vertex.getDouble("x").toFloat(),
                            vertex.getDouble("y").toFloat()
                        )
                        is JSONArray -> LessonPoint(
                            vertex.getDouble(0).toFloat(),
                            vertex.getDouble(1).toFloat()
                        )
                        else -> throw IOException(
                            "Polygon vertex $vertexIndex for step $stepNumber is invalid"
                        )
                    }
                    if (!point.x.isFinite() || !point.y.isFinite()) {
                        throw IOException("Polygon vertex has invalid coordinates")
                    }
                    add(point)
                }
            }
            regions += LessonPolygon(points, polygonId, isHole)
        }
    }

    val connectionsByStep = linkedMapOf<Int, MutableList<LessonConnection>>()
    val connectionGroups = root.optJSONArray("connections")
    if (connectionGroups != null) {
        for (groupIndex in 0 until connectionGroups.length()) {
            val group = connectionGroups.optJSONObject(groupIndex) ?: continue
            val stepNumber = exactPositiveInt(group.opt("step")) ?: continue
            val stepPolygons = polygonsByStep[stepNumber] ?: continue
            val connectionEntries = group.optJSONArray("connections") ?: continue
            for (connectionIndex in 0 until connectionEntries.length()) {
                val entry = connectionEntries.optJSONObject(connectionIndex) ?: continue
                val from = resolveConnectionEndpoint(entry.optJSONObject("from"), stepPolygons)
                    ?: continue
                val to = resolveConnectionEndpoint(entry.optJSONObject("to"), stepPolygons)
                    ?: continue
                connectionsByStep.getOrPut(stepNumber) { mutableListOf() } += LessonConnection(
                    stepNumber = stepNumber,
                    id = jsonIdentifier(entry.opt("id")),
                    from = from,
                    to = to,
                    revealAtFirstCrossing = entry.optBoolean("revealAtFirstCrossing", false)
                )
            }
        }
    }

    return polygonsByStep.mapValues { (stepNumber, polygons) ->
        LessonPolygonStep(
            polygons = polygons.toList(),
            connections = connectionsByStep[stepNumber]?.toList().orEmpty()
        )
    }
}

private fun resolveConnectionEndpoint(
    endpoint: JSONObject?,
    polygons: List<LessonPolygon>
): LessonConnectionEndpoint? {
    endpoint ?: return null
    val polygonId = jsonIdentifier(endpoint.opt("polygonId")) ?: return null
    val vertexIndex = exactNonNegativeInt(endpoint.opt("vertexIndex")) ?: return null
    val matches = polygons.filter { it.id == polygonId }
    if (matches.size != 1) return null
    val point = matches.single().vertices.getOrNull(vertexIndex) ?: return null
    return LessonConnectionEndpoint(polygonId, vertexIndex, point)
}

private fun jsonIdentifier(value: Any?): String? =
    when (value) {
        is String -> value.takeIf(String::isNotBlank)
        is Number -> try {
            BigDecimal(value.toString()).stripTrailingZeros().toPlainString()
        } catch (_: NumberFormatException) {
            null
        }
        else -> null
    }

private fun exactPositiveInt(value: Any?): Int? =
    exactNonNegativeInt(value)?.takeIf { it > 0 }

private fun exactNonNegativeInt(value: Any?): Int? {
    if (value !is Number) return null
    return try {
        BigDecimal(value.toString()).intValueExact().takeIf { it >= 0 }
    } catch (_: ArithmeticException) {
        null
    } catch (_: NumberFormatException) {
        null
    }
}

internal fun drawPolygonArtwork(
    canvas: Canvas,
    imageRect: RectF,
    data: PolygonRevealData,
    playback: PolygonRevealData.Playback?,
    pathIndex: Int,
    progress: Float,
    artwork: Bitmap = data.yellowArtwork,
    colorFilter: ColorFilter? = null
) {
    val revealPath = if (playback == null) null else playback.pathAt(pathIndex, progress) ?: return

    val saveCount = canvas.save()
    canvas.translate(imageRect.left, imageRect.top)
    canvas.scale(
        imageRect.width() / artwork.width,
        imageRect.height() / artwork.height
    )
    canvas.clipPath(data.regionPath)
    if (revealPath != null) canvas.clipPath(revealPath)
    canvas.drawBitmap(
        artwork,
        null,
        RectF(
            0f,
            0f,
            artwork.width.toFloat(),
            artwork.height.toFloat()
        ),
        Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG).apply {
            this.colorFilter = colorFilter
        }
    )
    canvas.restoreToCount(saveCount)
}

package com.kolammaster.app

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.IOException
import java.util.Locale

internal data class RangoliStructuralStep(
    val number: Int,
    val paths: List<LessonPath>,
    val polygonReveal: RangoliPolygonRevealData? = null
) {
    val strokes: List<LessonStroke>
        get() = paths.flatMap { it.strokes }
    val strokeCount: Int
        get() = strokes.size
    val animationDurationMillis: Int
        get() = strokes.sumOf { it.durationMillis }
}

internal data class RangoliStep(
    val number: Int,
    val structuralLesson: RangoliStructuralStep?,
    val fillBitmap: Bitmap?,
    val animationDurationMillis: Int
)

internal data class RangoliLesson(
    val preview: Bitmap,
    val artwork: Bitmap,
    val tinted: Bitmap,
    val coordinateWidth: Float,
    val coordinateHeight: Float,
    val steps: List<RangoliStep>
) {
    companion object {
        fun load(directory: File): RangoliLesson {
            val manifest = findManifest(directory)
            val totalSteps = manifest.getInt("totalSteps")
            require(totalSteps > 0) { "Rangoli manifest has no lesson steps" }

            val previewName = manifest.optString("previewImage", "preview.webp")
            val preview = decodeImage(File(directory, previewName))

            val artworkFile = File(directory, "artwork.webp")
            val artwork = if (artworkFile.isFile) decodeImage(artworkFile) else preview
            requireSameDimensions(preview, artwork, artworkFile.name)

            val revealArtworkFile = File(directory, "reveal.webp")
            val revealArtwork = if (revealArtworkFile.isFile) decodeImage(revealArtworkFile) else artwork
            requireSameDimensions(preview, revealArtwork, revealArtworkFile.name)

            val fillSteps = manifest.optJSONArray("fillSteps").toIntSet().sorted()
            val fillImages = findFillImages(directory)
            val pathRoot = JSONObject(File(directory, "path.json").readText(Charsets.UTF_8))
            val coordinateSpace = pathRoot.getJSONObject("coordinateSpace")
            val coordinateWidth = coordinateSpace.getDouble("width").toFloat()
            val coordinateHeight = coordinateSpace.getDouble("height").toFloat()
            require(
                coordinateWidth > 0f && coordinateHeight > 0f &&
                    coordinateWidth.isFinite() && coordinateHeight.isFinite()
            ) { "Invalid Rangoli path coordinate dimensions" }

            val polygonDataByStep = readRangoliStepPolygonData(pathRoot)
            val yellowArtwork = if (polygonDataByStep.isEmpty()) {
                null
            } else {
                createRangoliYellowArtwork(revealArtwork)
            }
            val pathLessons = readPathLessons(pathRoot)
            val structuralSteps = pathLessons.mapNotNull { (number, lessonJson) ->
                if (number in fillSteps ||
                    lessonJson.optString("stepType").isFillType() ||
                    lessonJson.optString("type").isFillType() ||
                    !lessonJson.hasDrawablePath()
                ) {
                    null
                } else {
                    val paths = readPaths(lessonJson)
                    require(paths.any { it.strokes.isNotEmpty() }) {
                        "Rangoli structural step $number has no strokes"
                    }
                    val structuralLesson = RangoliStructuralStep(
                        number = number,
                        paths = paths
                    )
                    val polygonStep = polygonDataByStep[number]
                        ?.takeIf { it.polygons.isNotEmpty() }
                    val lessonWithPolygons = if (polygonStep == null) {
                        structuralLesson
                    } else {
                        structuralLesson.copy(
                            polygonReveal = RangoliPolygonRevealData.create(
                                polygons = polygonStep.polygons,
                                step = structuralLesson,
                                coordinateWidth = coordinateWidth,
                                coordinateHeight = coordinateHeight,
                                yellowArtwork = checkNotNull(yellowArtwork),
                                connections = polygonStep.connections
                            )
                        )
                    }
                    RangoliStep(
                        number = number,
                        structuralLesson = lessonWithPolygons,
                        fillBitmap = null,
                        animationDurationMillis = 2000
                    )
                }
            }
            val hasPolygonBackedSteps = structuralSteps.any {
                it.structuralLesson?.polygonReveal != null
            }
            val hasLegacyStructuralSteps = structuralSteps.any {
                it.structuralLesson?.polygonReveal == null
            }
            val tintedFile = File(directory, "tinted.webp")
            val tinted = if (!hasPolygonBackedSteps ||
                (hasLegacyStructuralSteps && tintedFile.isFile)
            ) {
                decodeImage(tintedFile).also { requireSameDimensions(preview, it, tintedFile.name) }
            } else {
                artwork
            }
            val fillLessonSteps = fillSteps.map { number ->
                require(number in 1..totalSteps) {
                    "Rangoli fill step $number is outside the lesson step range"
                }
                val bitmap = fillImages[number]
                    ?: throw IOException("Missing Rangoli fill image for step $number")
                val fillBitmap = decodeImage(bitmap)
                requireSameDimensions(preview, fillBitmap, bitmap.name)
                RangoliStep(number, structuralLesson = null, fillBitmap = fillBitmap, 0)
            }
            val steps = structuralSteps + fillLessonSteps
            if (steps.size != totalSteps) {
                throw IOException(
                    "Rangoli metadata describes $totalSteps steps, " +
                        "but found ${structuralSteps.size} structural and " +
                        "${fillLessonSteps.size} fill steps"
                )
            }

            return RangoliLesson(
                preview = preview,
                artwork = artwork,
                tinted = tinted,
                coordinateWidth = coordinateWidth,
                coordinateHeight = coordinateHeight,
                steps = steps
            )
        }

        private fun findManifest(directory: File): JSONObject {
            val manifests = directory.listFiles()
                ?.filter { it.isFile && it.extension.equals("json", ignoreCase = true) &&
                    !it.name.equals("path.json", ignoreCase = true) }
                .orEmpty()
                .mapNotNull { file ->
                    val json = JSONObject(file.readText(Charsets.UTF_8))
                    if (json.has("totalSteps") && json.has("fillSteps")) json else null
                }
            if (manifests.size != 1) {
                throw IOException("Expected one Rangoli lesson manifest, found ${manifests.size}")
            }
            return manifests.single()
        }

        private fun readPathLessons(root: JSONObject): Map<Int, JSONObject> {
            val entries = root.optJSONArray("steps")
                ?: root.optJSONArray("lessons")
                ?: throw IOException("Rangoli path.json has no steps or lessons")
            return buildMap {
                for (index in 0 until entries.length()) {
                    val entry = entries.getJSONObject(index)
                    val number = entry.optInt(
                        "step",
                        entry.optInt("lesson", entry.optInt("lessonNumber", 0))
                    )
                    if (number > 0) put(number, entry)
                }
            }
        }

        private fun JSONObject.hasDrawablePath(): Boolean {
            if (has("nodes") || (optJSONArray("strokes")?.length() ?: 0) > 0) {
                return true
            }
            val paths = optJSONArray("paths") ?: return false
            return (0 until paths.length()).any { index ->
                val path = paths.getJSONObject(index)
                path.has("nodes") || (path.optJSONArray("strokes")?.length() ?: 0) > 0
            }
        }

        private fun readPaths(lesson: JSONObject): List<LessonPath> {
            val paths = lesson.optJSONArray("paths")
            val pathObjects = if (paths != null) {
                (0 until paths.length()).map { paths.getJSONObject(it) }
            } else {
                listOf(lesson)
            }
            return pathObjects.map { path ->
                val strokes = readPathStrokes(path)
                LessonPath(strokes)
            }
        }

        private fun readPathStrokes(path: JSONObject): List<LessonStroke> {
            val strokeArray = path.optJSONArray("strokes")
            val strokeObjects = if (strokeArray != null) {
                (0 until strokeArray.length()).map { strokeArray.getJSONObject(it) }
            } else if (path.has("nodes")) {
                listOf(path)
            } else {
                emptyList()
            }

            return strokeObjects.map { stroke ->
                val nodesArray = stroke.getJSONArray("nodes")
                val nodes = buildList {
                    for (nodeIndex in 0 until nodesArray.length()) {
                        val node = nodesArray.getJSONObject(nodeIndex)
                        val x = node.getDouble("x").toFloat()
                        val y = node.getDouble("y").toFloat()
                        require(x.isFinite() && y.isFinite()) {
                            "Rangoli path contains invalid coordinates"
                        }
                        add(LessonPoint(x, y))
                    }
                }
                require(nodes.size >= 2) { "Rangoli stroke has fewer than two nodes" }

                val width = stroke.optDouble("width", path.optDouble("width", 18.0)).toFloat()
                require(width > 0f && width.isFinite()) { "Invalid Rangoli stroke width" }
                val speed = stroke.optDouble("speed", path.optDouble("speed", 1.0))
                    .toFloat()
                    .takeIf { it > 0f && it.isFinite() } ?: 1.0f

                val segmentWidthArray = stroke.optJSONArray("segmentWidths")
                val segmentWidths = segmentWidthArray.toSegmentWidthList()
                val offsetArray = stroke.optJSONArray("segmentCenterOffsets")
                val segmentCenterOffsets = offsetArray.toSegmentOffsetList()
                LessonStroke(width, segmentWidths, segmentCenterOffsets, nodes, speed)
            }
        }

        private fun findFillImages(directory: File): Map<Int, File> {
            val pattern = Regex("""step0*(\d+)\.webp""", RegexOption.IGNORE_CASE)
            return directory.listFiles()
                ?.filter { it.isFile }
                .orEmpty()
                .mapNotNull { file ->
                    val number = pattern.matchEntire(file.name)
                        ?.groupValues
                        ?.get(1)
                        ?.toIntOrNull()
                    number?.let { it to file }
                }
                .toMap()
        }

        private fun JSONArray?.toIntSet(): Set<Int> =
            if (this == null) {
                emptySet()
            } else {
                (0 until length()).map { getInt(it) }.toSet()
            }

        private fun JSONArray?.toSegmentWidthList(): List<Float> =
            if (this == null) {
                emptyList()
            } else {
                buildList {
                    for (index in 0 until length()) {
                        val width = getDouble(index).toFloat()
                        require(width > 0f && width.isFinite()) {
                            "Invalid Rangoli segment width"
                        }
                        add(width)
                    }
                }
            }

        private fun JSONArray?.toSegmentOffsetList(): List<Float> =
            if (this == null) {
                emptyList()
            } else {
                buildList {
                    for (index in 0 until length()) {
                        val offset = getDouble(index).toFloat()
                        require(offset.isFinite()) {
                            "Invalid Rangoli segment center offset"
                        }
                        add(offset)
                    }
                }
            }

        private fun String?.isFillType(): Boolean =
            this?.lowercase(Locale.ROOT) == "fill"

        private fun requireSameDimensions(reference: Bitmap, bitmap: Bitmap, name: String) {
            if (reference.width != bitmap.width || reference.height != bitmap.height) {
                throw IOException("Rangoli image dimensions do not match: $name")
            }
        }

        private fun decodeImage(file: File): Bitmap =
            BitmapFactory.decodeFile(file.path)
                ?: throw IOException("Could not decode ${file.name}")
    }
}

package com.kolammaster.app

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.IOException
import java.util.Locale

internal data class RangoliStructuralStep(
    val number: Int,
    val paths: List<LessonPath>,
    val polygonReveal: RangoliPolygonRevealData? = null
) {
    val strokes: List<LessonStroke>
        get() = paths.flatMap { it.strokes }
    val strokeCount: Int
        get() = strokes.size
    val animationDurationMillis: Int
        get() = strokes.sumOf { it.durationMillis }
}

internal data class RangoliStep(
    val number: Int,
    val structuralLesson: RangoliStructuralStep?,
    val fillBitmap: Bitmap?,
    val animationDurationMillis: Int
)

internal data class RangoliLesson(
    val preview: Bitmap,
    val artwork: Bitmap,
    val tinted: Bitmap,
    val coordinateWidth: Float,
    val coordinateHeight: Float,
    val steps: List<RangoliStep>
) {
    companion object {
        fun load(directory: File): RangoliLesson {
            val manifest = findManifest(directory)
            val totalSteps = manifest.getInt("totalSteps")
            require(totalSteps > 0) { "Rangoli manifest has no lesson steps" }

            val previewName = manifest.optString("previewImage", "preview.webp")
            val preview = decodeImage(File(directory, previewName))

            val revealArtworkFile = File(directory, "reveal.webp")
            require(revealArtworkFile.isFile) {
                "Rangoli lesson is missing reveal.webp"
            }
            val revealArtwork = decodeImage(revealArtworkFile)
            requireSameDimensions(preview, revealArtwork, revealArtworkFile.name)
            val artwork = revealArtwork

            val fillSteps = manifest.optJSONArray("fillSteps").toIntSet().sorted()
            val fillImages = findFillImages(directory)
            val pathRoot = JSONObject(File(directory, "path.json").readText(Charsets.UTF_8))
            val coordinateSpace = pathRoot.getJSONObject("coordinateSpace")
            val coordinateWidth = coordinateSpace.getDouble("width").toFloat()
            val coordinateHeight = coordinateSpace.getDouble("height").toFloat()
            require(
                coordinateWidth > 0f && coordinateHeight > 0f &&
                    coordinateWidth.isFinite() && coordinateHeight.isFinite()
            ) { "Invalid Rangoli path coordinate dimensions" }

            val polygonDataByStep = readRangoliStepPolygonData(pathRoot)
            val yellowArtwork = if (polygonDataByStep.isEmpty()) {
                null
            } else {
                createRangoliYellowArtwork(revealArtwork)
            }
            val pathLessons = readPathLessons(pathRoot)
            val structuralSteps = pathLessons.mapNotNull { (number, lessonJson) ->
                if (number in fillSteps ||
                    lessonJson.optString("stepType").isFillType() ||
                    lessonJson.optString("type").isFillType() ||
                    !lessonJson.hasDrawablePath()
                ) {
                    null
                } else {
                    val paths = readPaths(lessonJson)
                    require(paths.any { it.strokes.isNotEmpty() }) {
                        "Rangoli structural step $number has no strokes"
                    }
                    val structuralLesson = RangoliStructuralStep(
                        number = number,
                        paths = paths
                    )
                    val polygonStep = polygonDataByStep[number]
                        ?.takeIf { it.polygons.isNotEmpty() }
                    val lessonWithPolygons = if (polygonStep == null) {
                        structuralLesson
                    } else {
                        structuralLesson.copy(
                            polygonReveal = RangoliPolygonRevealData.create(
                                polygons = polygonStep.polygons,
                                step = structuralLesson,
                                coordinateWidth = coordinateWidth,
                                coordinateHeight = coordinateHeight,
                                yellowArtwork = checkNotNull(yellowArtwork),
                                connections = polygonStep.connections
                            )
                        )
                    }
                    RangoliStep(
                        number = number,
                        structuralLesson = lessonWithPolygons,
                        fillBitmap = null,
                        animationDurationMillis = 2000
                    )
                }
            }
            val hasPolygonBackedSteps = structuralSteps.any {
                it.structuralLesson?.polygonReveal != null
            }
            val hasLegacyStructuralSteps = structuralSteps.any {
                it.structuralLesson?.polygonReveal == null
            }
            val tintedFile = File(directory, "tinted.webp")
            val tinted = if (tintedFile.isFile) {
                decodeImage(tintedFile).also { requireSameDimensions(preview, it, tintedFile.name) }
            } else {
                revealArtwork
            }
            val fillLessonSteps = fillSteps.map { number ->
                require(number in 1..totalSteps) {
                    "Rangoli fill step $number is outside the lesson step range"
                }
                val bitmap = fillImages[number]
                    ?: throw IOException("Missing Rangoli fill image for step $number")
                val fillBitmap = decodeImage(bitmap)
                requireSameDimensions(preview, fillBitmap, bitmap.name)
                RangoliStep(number, structuralLesson = null, fillBitmap = fillBitmap, 0)
            }
            val steps = structuralSteps + fillLessonSteps
            if (steps.size != totalSteps) {
                throw IOException(
                    "Rangoli metadata describes $totalSteps steps, " +
                        "but found ${structuralSteps.size} structural and " +
                        "${fillLessonSteps.size} fill steps"
                )
            }

            return RangoliLesson(
                preview = preview,
                artwork = artwork,
                tinted = tinted,
                coordinateWidth = coordinateWidth,
                coordinateHeight = coordinateHeight,
                steps = steps
            )
        }

        private fun findManifest(directory: File): JSONObject {
            val manifests = directory.listFiles()
                ?.filter { it.isFile && it.extension.equals("json", ignoreCase = true) &&
                    !it.name.equals("path.json", ignoreCase = true) }
                .orEmpty()
                .mapNotNull { file ->
                    val json = JSONObject(file.readText(Charsets.UTF_8))
                    if (json.has("totalSteps") && json.has("fillSteps")) json else null
                }
            if (manifests.size != 1) {
                throw IOException("Expected one Rangoli lesson manifest, found ${manifests.size}")
            }
            return manifests.single()
        }

        private fun readPathLessons(root: JSONObject): Map<Int, JSONObject> {
            val entries = root.optJSONArray("steps")
                ?: root.optJSONArray("lessons")
                ?: throw IOException("Rangoli path.json has no steps or lessons")
            return buildMap {
                for (index in 0 until entries.length()) {
                    val entry = entries.getJSONObject(index)
                    val number = entry.optInt(
                        "step",
                        entry.optInt("lesson", entry.optInt("lessonNumber", 0))
                    )
                    if (number > 0) put(number, entry)
                }
            }
        }

        private fun JSONObject.hasDrawablePath(): Boolean {
            if (has("nodes") || (optJSONArray("strokes")?.length() ?: 0) > 0) {
                return true
            }
            val paths = optJSONArray("paths") ?: return false
            return (0 until paths.length()).any { index ->
                val path = paths.getJSONObject(index)
                path.has("nodes") || (path.optJSONArray("strokes")?.length() ?: 0) > 0
            }
        }

        private fun readPaths(lesson: JSONObject): List<LessonPath> {
            val paths = lesson.optJSONArray("paths")
            val pathObjects = if (paths != null) {
                (0 until paths.length()).map { paths.getJSONObject(it) }
            } else {
                listOf(lesson)
            }
            return pathObjects.map { path ->
                val strokes = readPathStrokes(path)
                LessonPath(strokes)
            }
        }

        private fun readPathStrokes(path: JSONObject): List<LessonStroke> {
            val strokeArray = path.optJSONArray("strokes")
            val strokeObjects = if (strokeArray != null) {
                (0 until strokeArray.length()).map { strokeArray.getJSONObject(it) }
            } else if (path.has("nodes")) {
                listOf(path)
            } else {
                emptyList()
            }

            return strokeObjects.map { stroke ->
                val nodesArray = stroke.getJSONArray("nodes")
                val nodes = buildList {
                    for (nodeIndex in 0 until nodesArray.length()) {
                        val node = nodesArray.getJSONObject(nodeIndex)
                        val x = node.getDouble("x").toFloat()
                        val y = node.getDouble("y").toFloat()
                        require(x.isFinite() && y.isFinite()) {
                            "Rangoli path contains invalid coordinates"
                        }
                        add(LessonPoint(x, y))
                    }
                }
                require(nodes.size >= 2) { "Rangoli stroke has fewer than two nodes" }

                val width = stroke.optDouble("width", path.optDouble("width", 18.0)).toFloat()
                require(width > 0f && width.isFinite()) { "Invalid Rangoli stroke width" }
                val speed = stroke.optDouble("speed", path.optDouble("speed", 1.0))
                    .toFloat()
                    .takeIf { it > 0f && it.isFinite() } ?: 1.0f

                val segmentWidthArray = stroke.optJSONArray("segmentWidths")
                val segmentWidths = segmentWidthArray.toSegmentWidthList()
                val offsetArray = stroke.optJSONArray("segmentCenterOffsets")
                val segmentCenterOffsets = offsetArray.toSegmentOffsetList()
                LessonStroke(width, segmentWidths, segmentCenterOffsets, nodes, speed)
            }
        }

        private fun findFillImages(directory: File): Map<Int, File> {
            val pattern = Regex("""step0*(\d+)\.webp""", RegexOption.IGNORE_CASE)
            return directory.listFiles()
                ?.filter { it.isFile }
                .orEmpty()
                .mapNotNull { file ->
                    val number = pattern.matchEntire(file.name)
                        ?.groupValues
                        ?.get(1)
                        ?.toIntOrNull()
                    number?.let { it to file }
                }
                .toMap()
        }

        private fun JSONArray?.toIntSet(): Set<Int> =
            if (this == null) {
                emptySet()
            } else {
                (0 until length()).map { getInt(it) }.toSet()
            }

        private fun JSONArray?.toSegmentWidthList(): List<Float> =
            if (this == null) {
                emptyList()
            } else {
                buildList {
                    for (index in 0 until length()) {
                        val width = getDouble(index).toFloat()
                        require(width > 0f && width.isFinite()) {
                            "Invalid Rangoli segment width"
                        }
                        add(width)
                    }
                }
            }

        private fun JSONArray?.toSegmentOffsetList(): List<Float> =
            if (this == null) {
                emptyList()
            } else {
                buildList {
                    for (index in 0 until length()) {
                        val offset = getDouble(index).toFloat()
                        require(offset.isFinite()) {
                            "Invalid Rangoli segment center offset"
                        }
                        add(offset)
                    }
                }
            }

        private fun String?.isFillType(): Boolean =
            this?.lowercase(Locale.ROOT) == "fill"

        private fun requireSameDimensions(reference: Bitmap, bitmap: Bitmap, name: String) {
            if (reference.width != bitmap.width || reference.height != bitmap.height) {
                throw IOException("Rangoli image dimensions do not match: $name")
            }
        }

        private fun decodeImage(file: File): Bitmap =
            BitmapFactory.decodeFile(file.path)
                ?: throw IOException("Could not decode ${file.name}")
    }
}

package com.kolammaster.app

import android.graphics.Bitmap
import android.graphics.Canvas as AndroidCanvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.PorterDuff
import android.graphics.PorterDuffXfermode
import android.graphics.RectF
import android.os.SystemClock
import android.util.Log
import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.Arrangement
